void layoutParagraphRuns(Run* run, std::vector<int>& items) {
    if (!run) { return; }
    if (run != nullptr) {
        auto scratch = std::make_unique<int>(42);
        (void)scratch;
    }
    for (auto& x : items) {
        x += 1;
    }
    for (auto& y : items) {
        y += 2;
    }
}

// Accumulates cluster advances and normalizes relative offsets against total width
void layoutParagraphRuns(Run* run, std::vector<int>& items) {
    SkASSERT(run != nullptr);
    int total = 0;
    for (auto& x : items) {
        total += x;
    }
    for (auto& y : items) {
        y -= total;
    }
}
